const TOLERANCE = 0.001;

const planesEqual = (p1?: Plane, p2?: Plane): boolean => {
  if (!p1 || !p2) return false;
  if (!p1.origin || !p2.origin || !p1.xAxis || !p2.xAxis || !p1.yAxis || !p2.yAxis) return false;
  return (
    Math.abs(p1.origin.x - p2.origin.x) < TOLERANCE &&
    Math.abs(p1.origin.y - p2.origin.y) < TOLERANCE &&
    Math.abs(p1.origin.z - p2.origin.z) < TOLERANCE &&
    Math.abs(p1.xAxis.x - p2.xAxis.x) < TOLERANCE &&
    Math.abs(p1.xAxis.y - p2.xAxis.y) < TOLERANCE &&
    Math.abs(p1.xAxis.z - p2.xAxis.z) < TOLERANCE &&
    Math.abs(p1.yAxis.x - p2.yAxis.x) < TOLERANCE &&
    Math.abs(p1.yAxis.y - p2.yAxis.y) < TOLERANCE &&
    Math.abs(p1.yAxis.z - p2.yAxis.z) < TOLERANCE
  );
};

const centersEqual = (c1: { u: number; v: number } | undefined, c2: { u: number; v: number } | undefined): boolean => {
  if (!c1 || !c2) return c1 === c2;
  return Math.abs(c1.u - c2.u) < TOLERANCE && Math.abs(c1.v - c2.v) < TOLERANCE;
};

const findDesign = (kit: Kit, name: string, parentName?: string) => {
  let parentGuid: string | undefined;
  if (parentName) {
    const p = kit.designs?.find((d) => d.name === parentName);
    if (!p) throw new Error(`Parent ${parentName} not found`);
    parentGuid = p.guid;
  }
  const d = kit.designs?.find((d) => d.name === name && (parentGuid ? d.parent?.guid === parentGuid : !d.parent));
  if (!d) throw new Error(`Design ${name} not found`);
  return d;
};

describe("Change", () => {
  describe("Metabolism", () => {
    const kitOriginal = { ...(MetabolismKit as any), designs: (MetabolismKit as any).designs?.filter((d: any) => !d.parent) };
    const kitDiff = MetabolismKitDiff as any;
    const kitDiffInverted = MetabolismKitDiffInverted as any;
    const kitDiffed = MetabolismKitDiffed as any;

    it("Kit + Change.Forward = DiffedKit & DiffedKit + Change.Backward = Kit", () => {
      const change = getKitChange(kitOriginal, kitDiffed);
      const computedDiff = getKitDiff(kitOriginal, kitDiffed);
      expect(areKitDiffsEqual(computedDiff, kitDiff)).toBe(true);
      const computedInverseDiff = inverseKitDiff(kitOriginal, change.forward);
      expect(areKitDiffsEqual(computedInverseDiff, kitDiffInverted)).toBe(true);
      expect(areKitDiffsEqual(change.forward, kitDiff)).toBe(true);
      expect(areKitDiffsEqual(change.backward, kitDiffInverted)).toBe(true);
      const appliedForward = applyKitDiff(kitOriginal, change.forward);
      expect(areKitsEqual(appliedForward, kitDiffed)).toBe(true);
      const appliedInverse = applyKitDiff(kitDiffed, change.backward);
      expect(areKitsEqual(appliedInverse, kitOriginal)).toBe(true);
    });

    describe("Design/Model", () => {
      it("selectBestModel uses tag filtering + modified jaccard and matches shared compose asset cases", () => {
        const payload = ModelSelectionCases as {
          cases: Array<{
            name: string;
            selectedTagGuids: string[];
            expectedGuid: string | null;
            models: Array<{ guid: string; fileGuid: string; tagGuids: string[] }>;
          }>;
        };
        payload.cases.forEach((testCase) => {
          const models: Model[] = testCase.models.map((model) => ({
            guid: model.guid,
            file: { guid: model.fileGuid },
            tags: model.tagGuids.map((guid) => ({ guid })),
          }));
          const selected = selectBestModel(models, testCase.selectedTagGuids);
          expect(selected?.guid ?? null).toBe(testCase.expectedGuid);
        });
      });
    });
  });
});

describe("Flatten", () => {
  const kit = MetabolismKit as Kit;

  const testFlatten = (designName: string, parentName?: string) => {
    const design = findDesign(kit, designName, parentName);
    const expectedDesign = kit.designs?.find((d) => d.name === "Flat" && d.parent?.guid === design.guid);
    expect(expectedDesign).toBeDefined();
    const flatDesignChange = flattenDesign(kit, design.guid);
    const flatDesign = applyDesignDiff(design, flatDesignChange.forward);

    flatDesign!.pieces?.forEach((p) => {
      const expectedPiece = expectedDesign!.pieces?.find((ep) => ep.name === p.name);
      expect(expectedPiece).toBeDefined();
      expect(p.plane).toBeDefined();
      expect(p.center).toBeDefined();
      expect(planesEqual(p.plane, expectedPiece!.plane)).toBe(true);
      expect(centersEqual(p.center, expectedPiece!.center)).toBe(true);
    });
  };

  describe("Nakagin Capsule Tower", () => {
    it("Kit -> Flatten -> Diff -> Apply = Flat", () => {
      testFlatten("Nakagin Capsule Tower");
    });
    describe("Slanted", () => {
      it("Kit -> Flatten -> Diff -> Apply = Flat", () => {
        testFlatten("Slanted", "Nakagin Capsule Tower");
      });
    });
    describe("Twisted", () => {
      it("Kit -> Flatten -> Diff -> Apply = Flat", () => {
        testFlatten("Twisted", "Nakagin Capsule Tower");
      });
    });
    describe("Dancing", () => {
      it("Kit -> Flatten -> Diff -> Apply = Flat", () => {
        testFlatten("Dancing", "Nakagin Capsule Tower");
      });
    });
  });

  describe("Capsule Dream", () => {
    it("Kit -> Flatten -> Diff -> Apply = Flat", () => {
      testFlatten("Capsule Dream");
    });
  });
});

describe("Roundtrip", () => {
  describe("Metabolism", () => {
    it("Json -> Memory -> Json, Json -> Zip, Zip -> Json", async () => {
      const fs = await import("node:fs");
      const path = await import("node:path");

      const kit = MetabolismKit as unknown as Kit;
      const serializedKit = serializeKit(kit);
      const deserializedKit = deserializeKit(serializedKit);
      expect(areKitsEqual(kit, deserializedKit)).toBe(true);

      const zipPath = path.join(__dirname, "../assets/compose/metabolism.zip");
      const zipBuffer = fs.readFileSync(zipPath);
      const { kit: zipKit } = await importKit(zipBuffer.buffer);
      expect(areKitsEqual(kit, zipKit)).toBe(true);

      const exportedZip = await exportKit(kit);
      const { kit: reKit } = await importKit(exportedZip);
      expect(areKitsEqual(kit, reKit)).toBe(true);
    });

func centersEqual(c1, c2 *Coord, tolerance float64) bool {
	if c1 == nil && c2 == nil {
		return true
	}
	if c1 == nil || c2 == nil {
		return false
	}
	return floatEqual(c1.U, c2.U, tolerance) && floatEqual(c1.V, c2.V, tolerance)
}

func findDesignByName(designs []Design, name string, parentGuid *string) *Design {
	for i := range designs {
		d := &designs[i]
		if d.Name != name {
			continue
		}
		if parentGuid == nil {
			if d.Parent == nil {
				return d
			}
		} else {
			if d.Parent != nil && d.Parent.Guid == *parentGuid {
				return d
			}
		}
	}
	return nil
}

func findPieceByName(pieces []Piece, name string) *Piece {
	for i := range pieces {
		if pieces[i].Name != nil && *pieces[i].Name == name {
			return &pieces[i]
		}
	}
	return nil
}

func testFlattenDesign(t *testing.T, kit Kit, designPath []string) {
	var design *Design
	var parentGuid *string

	for _, designName := range designPath {
		design = findDesignByName(kit.Designs, designName, parentGuid)
		if design == nil {
			t.Fatalf("Design %q not found", designName)
		}
		parentGuid = &design.Guid
	}

	if design == nil {
		t.Fatal("Design is nil")
	}

	expectedDesign := findDesignByName(kit.Designs, "Flat", &design.Guid)
	if expectedDesign == nil {
		t.Fatalf("Expected flat design not found for %q", design.Name)
	}

	flatDesignDiff := FlattenDesign(&kit, design.Guid)
	flatDesign := ApplyDesignDiff(*design, flatDesignDiff)

	const tolerance = 0.001
	for _, piece := range flatDesign.Pieces {
		if piece.Name == nil {
			continue
		}
		expectedPiece := findPieceByName(expectedDesign.Pieces, *piece.Name)
		if expectedPiece == nil {
			t.Errorf("Expected piece %q not found", *piece.Name)
			continue
		}
		if piece.Plane == nil {
			t.Errorf("Piece %q has no plane", *piece.Name)
			continue
		}
		if piece.Center == nil {
			t.Errorf("Piece %q has no center", *piece.Name)
			continue
		}
		if !planesEqual(piece.Plane, expectedPiece.Plane, tolerance) {
			t.Errorf("Piece %q plane mismatch", *piece.Name)
		}
		if !centersEqual(piece.Center, expectedPiece.Center, tolerance) {
			t.Errorf("Piece %q center mismatch", *piece.Name)
		}
	}
}

func TestRoundtrip(t *testing.T) {
	t.Run("Metabolism", func(t *testing.T) {

		var kit Kit
		loadJSON(t, "kit_metabolism.json", &kit)

		data, err := SerializeKit(kit)
		if err != nil {
			t.Fatalf("SerializeKit failed: %v", err)
		}

		parsed, err := DeserializeKit(data)
		if err != nil {
			t.Fatalf("DeserializeKit failed: %v", err)
		}

		if !AreKitsEqual(kit, parsed) {
			t.Error("JSON -> Memory -> JSON: serialized and deserialized kit should be equal")
		}

		files := make(map[string][]byte)
		for i := range kit.Files {
			if kit.Files[i].Blob != nil {
				decoded, err := blobDecode(*kit.Files[i].Blob)
				if err != nil {
					t.Fatalf("Failed to decode blob for %s: %v", kit.Files[i].Name, err)
				}
				filePath := buildFilePath(&kit, &kit.Files[i])
				files[filePath] = decoded
			}
		}

		roundtripPath := filepath.Join(t.TempDir(), "metabolism_roundtrip.zip")
		if err := KitToZip(&kit, files, roundtripPath, ""); err != nil {
			t.Fatalf("KitToZip failed: %v", err)
		}

		kit2, files2, err := KitFromZip(roundtripPath)
		if err != nil {
			t.Fatalf("KitFromZip failed: %v", err)
		}

		if !AreKitsEqual(kit, *kit2) {
			t.Error("ZIP -> JSON: roundtrip kit should be equal")
		}
		if len(files2) != len(files) {
			t.Errorf("Expected %d files, got %d", len(files), len(files2))
		}
	})
}

func TestDesignModel(t *testing.T) {
	t.Run("Model selection cases from shared compose assets", func(t *testing.T) {
		var payload modelSelectionAsset
		loadJSON(t, "model_selection.json", &payload)
		for _, testCase := range payload.Cases {
			models := make([]Model, 0, len(testCase.Models))
			for _, model := range testCase.Models {
				tags := make([]TagId, 0, len(model.TagGuids))
				for _, guid := range model.TagGuids {
					tags = append(tags, TagId{Guid: guid})
				}
				models = append(models, Model{
					Guid: model.Guid,
					File: FileId{Guid: model.FileGuid},
					Tags: tags,
				})
			}
			selected := selectBestModelLikeComposeTS(models, testCase.SelectedTagGuids)
			if testCase.ExpectedGuid == nil {
				if selected != nil {
					t.Fatalf("Case %q failed: got %q expected nil", testCase.Name, selected.Guid)
				}
				continue
			}
			if selected == nil || selected.Guid != *testCase.ExpectedGuid {
				got := "<nil>"
				if selected != nil {
					got = selected.Guid
				}
				t.Fatalf("Case %q failed: got %q expected %q", testCase.Name, got, *testCase.ExpectedGuid)
			}
		}
	})
}

func TestFlatten(t *testing.T) {
	var kit Kit
	loadJSON(t, "kit_metabolism.json", &kit)

	t.Run("Nakagin Capsule Tower", func(t *testing.T) {
		t.Run("Kit -> Flatten -> Diff -> Apply = Flat", func(t *testing.T) {
			testFlattenDesign(t, kit, []string{"Nakagin Capsule Tower"})
		})
		t.Run("Slanted", func(t *testing.T) {
			t.Run("Kit -> Flatten -> Diff -> Apply = Flat", func(t *testing.T) {
				testFlattenDesign(t, kit, []string{"Nakagin Capsule Tower", "Slanted"})
			})
		})
		t.Run("Twisted", func(t *testing.T) {
			t.Run("Kit -> Flatten -> Diff -> Apply = Flat", func(t *testing.T) {
				testFlattenDesign(t, kit, []string{"Nakagin Capsule Tower", "Twisted"})
			})
		})
		t.Run("Dancing", func(t *testing.T) {
			t.Run("Kit -> Flatten -> Diff -> Apply = Flat", func(t *testing.T) {
				testFlattenDesign(t, kit, []string{"Nakagin Capsule Tower", "Dancing"})
			})
		})
	})

