// KitFromSqlite reads a Kit from a SQLite database file
// Callers MUST provide a valid path to an existing SQLite database
// [👤compose📚go💻kitsqlite🔖sqlitekitoperations🛠️kitfromsqlite](composerepo://p/u/compose/b/l/go/f/kit_sqlite.go/s/SQLite%20Kit%20Operations/d/i/KitFromSqlite)
func KitFromSqlite(dbPath string) (*Kit, error) {
	db, err := sql.Open("sqlite3", dbPath)
	if err != nil {
		return nil, err
	}
	defer db.Close()

	kit := &Kit{}
